import SwiftUI
import UniformTypeIdentifiers
struct StrategyResearchView:View {
 @EnvironmentObject var store:MarketStore
 @AppStorage("research.capital") private var capital="1000000"
 @AppStorage("research.fee") private var fee="5"
 @AppStorage("research.slip") private var slip="5"
 @AppStorage("research.profile") private var profileRaw="CLASSIC"
 var profile:StrategyProfile{StrategyProfile(rawValue:profileRaw) ?? .classic}
 @State private var confirmPaper=false
 @State private var importing=false
 @State private var exporting=false
 @State private var busy=false
 @State private var result="CSV를 선택하면 휴대폰 안에서 백테스트합니다."
 @State private var csvReport=Data()
 @State private var document=JSONDocument(data:Data())
 var body:some View{NavigationStack{ScrollView{VStack(alignment:.leading,spacing:18){NavigationLink{CommunityView()}label:{Label("국내 커뮤니티 분석",systemImage:"bubble.left.and.bubble.right").frame(maxWidth:.infinity,minHeight:48)}.modifier(CareControl());NavigationLink{BackgroundServerView()}label:{Label("백그라운드 · Ubuntu 서버",systemImage:"server.rack").frame(maxWidth:.infinity,minHeight:48)}.modifier(CareControl());
 VStack(alignment:.leading,spacing:14){Text("전략 실행").font(.title2.bold());Picker("전략 프로필",selection:$profileRaw){ForEach(StrategyProfile.allCases,id:\.rawValue){p in Text(p.label).tag(p.rawValue)}}.pickerStyle(.menu);Text(profile.detail).font(.caption).foregroundStyle(.secondary);Text("선택은 새 CSV·기기 세션에만 적용합니다. 서버 전략은 기존 설정을 유지하며 성과 개선은 보장하지 않습니다.").font(.caption2).foregroundStyle(.secondary);Text("EMA9/21 현물 매수·청산 · 모의 전용").font(.subheadline).foregroundStyle(.secondary);Text("시작 자본 (입력 가격 통화)").font(.caption).foregroundStyle(.secondary);TextField("시작 자본 (입력 가격 통화)",text:$capital).keyboardType(.decimalPad).textFieldStyle(.roundedBorder);HStack{VStack(alignment:.leading){Text("수수료 (bps)").font(.caption);TextField("수수료 bps",text:$fee).keyboardType(.decimalPad)};VStack(alignment:.leading){Text("슬리피지 (bps)").font(.caption);TextField("슬리피지 bps",text:$slip).keyboardType(.decimalPad)}}.textFieldStyle(.roundedBorder);Button("입력값 기본값 복원"){capital="1000000";fee="5";slip="5";profileRaw="CLASSIC"}.frame(minHeight:44);Text("입력은 이 기기에 저장되며 실행 중인 모의계좌는 바뀌지 않습니다.").font(.caption).foregroundStyle(.secondary);Text("30봉 준비 · 종가 신호 후 다음 시가 체결 · 손절/익절 동시 도달 시 손절 우선").font(.caption).foregroundStyle(.secondary);Button{importing=true}label:{Label("CSV 백테스트 실행",systemImage:"play.rectangle").frame(maxWidth:.infinity,minHeight:48)}.modifier(CareControl()).disabled(busy);Button("합성 테스트32봉 실행"){runSynthetic()}.frame(minHeight:44).disabled(busy);Text("합성 자료는 입력·수수료 확인용이며 실제 시세/성과가 아닙니다.").font(.caption2).foregroundStyle(.secondary);if busy{ProgressView()};Text(result).font(.system(.caption,design:.monospaced)).textSelection(.enabled);if !csvReport.isEmpty{ResearchAnalyticsView(data:csvReport)};Button("CSV 결과 JSON 저장"){document=JSONDocument(data:csvReport);exporting=true}.disabled(csvReport.isEmpty).frame(minHeight:44)
 }.modifier(CareCard())
 VStack(alignment:.leading,spacing:14){if let paper=store.paper{let overview=PaperAccountOverview(paper);Text("현재 기기 모의계좌").font(.headline);Text("\(overview.symbol) · \(paper.engine.profile.label) · \(overview.state)").font(.subheadline);Text("관측 평가액 \(money(overview.equity))").font(.title2.bold()).monospacedDigit();Text("현금 \(money(overview.cash)) · 보유 \(overview.quantity.formatted(.number.precision(.fractionLength(8))))").font(.caption).monospacedDigit();Divider()};Text("실시간 모의매매").font(.title2.bold());Text("\(store.selected) · 업비트 KRW · 관측 가격 1분봉").font(.subheadline);Text("첫 부분봉 제외, 30개 완성봉 준비가 필요해요. 수신 공백·백그라운드에서는 일시 정지하며 남은 모의 보유분은 유지합니다. 새 세션은 모의계좌를 초기화합니다.").font(.caption).foregroundStyle(.secondary);Button{startPaper()}label:{Label("새 실시간 모의세션 시작",systemImage:"play.circle").frame(maxWidth:.infinity,minHeight:48)}.modifier(CareControl());Button("모의매매 일시 정지"){store.paper?.pause("사용자 일시 정지");store.objectWillChange.send()}.frame(minHeight:44);if let p=store.paper{ProgressView(value:Double(min(p.engine.bars,30)),total:30);Text("준비 \(min(p.engine.bars,30))/30봉 · \(p.engine.halted ? "신규 진입 중지":"신호 관찰")").font(.caption).foregroundStyle(.secondary);Text((p.running ? "실행 중 · ":"정지 · ")+p.symbol+"\n"+p.engine.summary).font(.system(.caption,design:.monospaced)).textSelection(.enabled);Button("모의계좌 JSON 저장"){document=JSONDocument(data:p.engine.report());exporting=true}.frame(minHeight:44)}
 }.modifier(CareCard())
 NavigationLink{ResearchView()}label:{Label("결과 JSON 열기",systemImage:"doc.text").frame(maxWidth:.infinity,minHeight:48)}.modifier(CareControl())
 Text("모바일 EMA는 별도 엔진입니다. 기존 v1.6·v1.1 멀티팩터·v1.7 구현과 동일하지 않습니다. 실거래 자동매매 코드는 동봉된 operator 폴더에서 사용자가 직접 준비·가동합니다. 앱에는 실제 주문 기능이 없습니다.").font(.caption).foregroundStyle(.secondary)
 }.padding(20)}.background(Color(uiColor:.systemGroupedBackground)).navigationTitle("연구실").onChange(of:capital){capital=ResearchSupport.boundedDraft($0)}.onChange(of:fee){fee=ResearchSupport.boundedDraft($0)}.onChange(of:slip){slip=ResearchSupport.boundedDraft($0)}.confirmationDialog("모의계좌를 새로 만들까요?",isPresented:$confirmPaper,titleVisibility:.visible){Button("새 모의세션 시작",role:.destructive){performStartPaper()};Button("취소",role:.cancel){}}message:{Text("현재 모의계좌의 잔고와 상태를 초기화합니다. 먼저 결과 JSON을 저장하세요.")}.fileImporter(isPresented:$importing,allowedContentTypes:[.commaSeparatedText,.plainText],allowsMultipleSelection:false){r in switch r{case .success(let urls):if let u=urls.first{loadCSV(u)};case .failure(let e):result=e.localizedDescription}}.fileExporter(isPresented:$exporting,document:document,contentType:.json,defaultFilename:"strategy-paper-result"){r in if case .failure(let e)=r{result=e.localizedDescription}}}}
 func runSynthetic(){do{let(c,f,s)=try parameters();let e=try StrategyCore.backtest(StrategyCore.syntheticRows(),c,f,s,profile);result="합성 테스트 · 실제 시세/성과 아님\n"+e.summary;csvReport=e.report();document=JSONDocument(data:csvReport)}catch{result=error.localizedDescription}}
 func parameters()throws->(Double,Double,Double){guard let c=Double(capital),let f=Double(fee),let s=Double(slip)else{throw StrategyError.invalid("숫자를 입력하세요")};_ = try StrategyCore(c,f,s);return(c,f,s)}
 func startPaper(){if store.paper != nil{confirmPaper=true}else{performStartPaper()}}
 func performStartPaper(){do{let(c,f,s)=try parameters();store.paper=try LivePaper(store.selected,c,f,s,profile);store.setConnected(true)}catch{result=error.localizedDescription}}
 func loadCSV(_ url:URL){do{let(c,f,s)=try parameters();let runProfile=profile;busy=true;Task{let resultValue=await Task.detached(priority:.userInitiated){()->(String,Data) in let access=url.startAccessingSecurityScopedResource();defer{if access{url.stopAccessingSecurityScopedResource()}};do{let handle=try FileHandle(forReadingFrom:url);defer{try? handle.close()};let data=try handle.read(upToCount:8*1024*1024+1) ?? Data();guard data.count<=8*1024*1024,let text=String(data:data,encoding:.utf8)else{throw StrategyError.invalid("UTF-8 CSV 8MB 이하 필요")};let e=try StrategyCore.backtest(StrategyCore.csv(text),c,f,s,runProfile);return(e.summary,e.report())}catch{return(error.localizedDescription,Data())}}.value;result=resultValue.0;csvReport=resultValue.1;document=JSONDocument(data:resultValue.1);busy=false}}catch{result=error.localizedDescription}}
}
